from pathlib import Path
import json,statistics
w=Path(__file__).resolve().parent;root=Path(json.loads((w/'report-location.json').read_text())['path'])
def read(p):return json.loads(p.read_text())
s=read(root/'results/paired-summary.json')['contexts'][0];raw=read(root/'results/paired-raw.json');old=read(root/'baseline-tail-summary.json')['contexts'][0];audit=read(root/'independent-audit.json');old_audit=read(root/'baseline-tail-audit.json');profile=read(root/'profile32k-analysis.json');old_profile=read(root/'baseline-tail-profile.json');freeze=read(root/'inputs/freeze.json')
valid_pairs=[pair for pair in raw['pairs'] if pair['valid']]
invalid_raw=[pair for pair in raw['pairs'] if not pair['valid']]
assert len(valid_pairs)==5 and len(invalid_raw)==1
assert (invalid_raw[0]['context'],invalid_raw[0]['repetition'],invalid_raw[0]['attempt'])==(32768,4,1)
assert invalid_raw[0]['invalid_reason'].startswith('Host shutdown/restart interrupted pair 4 attempt 1')
latency=statistics.median(p['candidate']['prefill_ms']/p['oracle']['prefill_ms'] for p in valid_pairs);old_latency=1/old['candidate_over_oracle']['prefill_tps']['median']
assert s['candidate']['prefill_ms']['median']<old['candidate']['prefill_ms']['median'] and latency<old_latency,'Optimization did not improve baseline; retain evidence and reassess'
lines=['# Rust Star: direct dense Q8 native output projection','', 'Native 4K tails use eight aligned dense-Q8 dispatches for output-low projection. The existing kernel writes directly into token-major rows with a physical pitch of 8192, avoiding the grouped map and scatter epilogue. Native group IDs, map scratch and host ID initialization are omitted. Twenty temporary buffers remain pooled. No Metal kernel source or arithmetic was changed; legacy controls retain their original grouped path.','', '## Five-pair result','', 'Five alternating AB/BA pairs and one warmup per engine completed. A host shutdown/restart interrupted pair 4 during its oracle half. The original attempt and its completed Rust measurement remain preserved; the documented recovery procedure reran the entire pair as attempt 2. Every other pair and both warmups passed on attempt 1. The campaign therefore spans the restart, and the report includes the recovery host state. Initial selection belongs to prefill; decode timing includes evaluation, selection and commitment. Correctness collection and profiling are disabled during the paired block. These are 32K/128 development results.','', '| Metric | Rust median | Oracle-v5 median |','|---|---:|---:|']
for label,key,scale,unit in [('Prefill','prefill_ms',.001,'s'),('Steady decode','gen_steady_tps',1,'tokens/s'),('First decode step','gen_first_ms',1,'ms')]:lines.append(f"| {label} | {s['candidate'][key]['median']*scale:.3f} {unit} | {s['oracle'][key]['median']*scale:.3f} {unit} |")
lines.append(f"| Peak process memory | {audit['memory_distributions']['candidate']['median']:.3f} GiB | {audit['memory_distributions']['oracle']['median']:.3f} GiB |")
lines+=['','| Distribution (5 runs each) | Median | MAD | Min–max |','|---|---:|---:|---:|']
for role,label in [('candidate','Rust'),('oracle','Oracle-v5')]:
 for key,name,scale in [('prefill_ms','prefill seconds',.001),('gen_steady_tps','steady decode tokens/s',1)]:
  d=s[role][key]
  lines.append(f"| {label} {name} | {d['median']*scale:.3f} | {d['mad']*scale:.3f} | {d['min']*scale:.3f}–{d['max']*scale:.3f} |")
lines+=['','| Pair | Order | Rust prefill s | Reference prefill s | Rust/reference |','|---|---|---:|---:|---:|']
for pair in valid_pairs:
 lines.append(f"| {pair['repetition']} | {pair['order']} | {pair['candidate']['prefill_ms']/1000:.3f} | {pair['oracle']['prefill_ms']/1000:.3f} | {pair['candidate']['prefill_ms']/pair['oracle']['prefill_ms']:.5f} |")
observations=[json.loads(line) for line in (root/'load-observations.jsonl').read_text().splitlines()]
video=[obs['at_utc'] for obs in observations if any(p['process'] in ('OBS','UVCAssistant','VTDecoderXPCService') for p in obs['cpu_processes'])]
if video:lines+=['',f"OBS/camera/video activity appears in the process observations from {min(video)} through {max(video)} (the observer also covers the separate profile). Background load varies across the observations. All pairs are retained; the exact latency improvement cannot be attributed solely to the code change under these varying background conditions."]
lines+=['','Source review, report-helper edits and a temporary-copy Rustfmt syntax check (about six seconds during pair 3) also occurred on the host. Runtime source and measured binaries stayed frozen; no runtime build or second model process ran alongside the timed block. This incidental host work is retained with the background-load qualifications.']
host_before=read(root/'inputs/host-before.json');host_after=read(root/'inputs/host-after-pairs.json')
lines+=['', f"Host swap before the campaign: `{host_before['memory']['swap']}`; after the timed block: `{host_after['swap']}`. Peak process memory is an observed residency measure under these host conditions, not proof of a lower allocation requirement."]
lines+=['',f"Paired Rust/reference prefill latency ratio: {latency:.5f}. Steady decode ratio: {s['candidate_over_oracle']['gen_steady_tps']['median']:.5f}. Complete median/MAD/range distributions and independent recomputation are included.",'','## Change from the native-tail scratch baseline','']
for role in ['candidate','oracle']:
 before=old[role]['prefill_ms']['median']/1000;after=s[role]['prefill_ms']['median']/1000;lines.append(f"- {role.capitalize()} median prefill: {before:.3f} → {after:.3f} s ({(after/before-1)*100:+.2f}% latency).")
lines += [f"- Rust steady decode: {old['candidate']['gen_steady_tps']['median']:.3f} → {s['candidate']['gen_steady_tps']['median']:.3f} tokens/s; paired Rust/reference ratio {old['candidate_over_oracle']['gen_steady_tps']['median']:.5f} → {s['candidate_over_oracle']['gen_steady_tps']['median']:.5f}.",f"- Reference-normalized prefill improvement across campaigns: {old_latency/latency:.3f}× (paired latency ratio {old_latency:.5f} → {latency:.5f}).",f"- Rust peak memory: {old_audit['memory_distributions']['candidate']['median']:.3f} → {audit['memory_distributions']['candidate']['median']:.3f} GiB.",'','Both campaigns use the same pinned oracle-v5, model, prompt, full-output targets and greedy transcript. They are separate host sessions; the normalized comparison is descriptive. Background applications remained active, and full load/thermal observations are included.',f"The audit records {len(audit['unusual_thermal_observations'])} unusual thermal observations.",'','## Validation','', '- 312 Rust tests pass. The unchanged Python toolkit retains its 93-test acceptance evidence.', '- Fresh complete 32K output-only and diagnostic runs match every prefill logit and all 128 full decode outputs to oracle-v5. Every accepted internal HC target through 24K matches.', '- The 12K native control, detailed 8K legacy control, 2K control and two retained reset/reuse cycles pass. No fixture was updated or tolerance introduced.', '- The full v5 tensors, reference repeatability and tokenizer evidence are reused unchanged from the audited baseline report. Historical failed oracle/diagnostic attempts remain preserved and explicitly separate from this candidate.', '- Existing decoder, prefix, SSD and distributed implementations are unchanged. The 32-row standalone controls retain their diagnostic conversion and output assembly. Native tails use 31 dispatches instead of 25; eight dense group dispatches replace a map and grouped matmul. A separate profiled full-output gate also passes all tensors, with 2,583 component intervals audited.', '', '## Isolated profile','', 'Host elapsed time includes command waits and is not additive with GPU time.','', '| Stage group | GPU seconds | Host elapsed seconds | Calls |','|---|---:|---:|---:|']
for name,g in sorted(profile['group_totals'].items(),key=lambda item:item[1]['gpu_ms'],reverse=True):lines.append(f"| {name} | {g['gpu_ms']/1000:.3f} | {g['host_elapsed_ms']/1000:.3f} | {g['calls']} |")
a=old_profile['group_totals']['even/tail'];b=profile['group_totals']['even/tail'];leading=max(profile['group_totals'],key=lambda n:profile['group_totals'][n]['gpu_ms'])
lines+=['',f"Even-layer tails retain 147 stage calls; GPU time changes from {a['gpu_ms']/1000:.3f} to {b['gpu_ms']/1000:.3f} s and host time from {a['host_elapsed_ms']/1000:.3f} to {b['host_elapsed_ms']/1000:.3f} s. This separate instrumented run is ineligible for throughput claims. The current tail profile splits nine component encoders and samples counters, whereas the older aggregate profile did not; the difference includes changed instrumentation and cannot isolate the kernel change.",'',f"The next measured stage group is `{leading}`. Use the component breakdown before choosing another optimization, preserving full v5 C0 and lifecycle; track peak memory alongside speed. Broader contexts and the 256K headline workload remain future work.",'','## Reproduction','',f"Candidate source `{freeze['candidate_commit']}`, executable SHA `{freeze['candidate_sha256']}`.",f"Oracle source `{freeze['oracle_commit']}`, executable SHA `{freeze['oracle_sha256']}`.",f"Frozen plan SHA `{freeze['plan_sha256']}`.",'','Run `python3 verify.py` here without the model. It verifies all artifact hashes, raw paired statistics, transcripts, complete v5 tensors, candidate gates and profile coverage. `implementation.patch` records the runtime changes; `inputs/plan-template.json` and `portability.json` retain the frozen configuration and path-redaction provenance.','']
(root/'README.md').write_text('\n'.join(lines))

components=profile['tail_component_attributed_gpu_ms'];total=sum(components.values())
with (root/'README.md').open('a') as f:
 f.write("\n## Native tail components\n\nThese nine intervals partition their parent tail GPU time. Counter shares are scaled to each completed command; they are perturbed diagnostic attribution, not standalone kernel latency. All 2,583 rows also pass coverage, ordering and conservation checks.\n\n| Component | Attributed GPU seconds | Share |\n|---|---:|---:|\n")
 for name,value in sorted(components.items(),key=lambda item:-item[1]):f.write(f"| {name} | {value/1000:.3f} | {value/total*100:.2f}% |\n")
 f.write("\nThe preceding exact-gated component baseline is preserved in [its own report](../32k-tail-components-e7b81aa2/README.md).\n")
